let linked=false,member=null,user=null,consentRequired=false,folder=localStorage.getItem('nv_game_folder')||'';
const gameAppName=value=>String(value||'').split('/').pop().split(String.fromCharCode(92)).pop();
const validGameApp=value=>['gta6.exe','gta vi.exe','gtavi.exe'].includes(gameAppName(value).toLowerCase());
const $=s=>document.querySelector(s),play=$('#playBtn');
play.disabled=true;
let statusRefresh=null;
let socialState={status:'signedOut',friends:[]};
const seededProgress={};
let playerProgress={completionPercent:0,trophiesEarned:0,playtimeSeconds:0};
const leaderboardUpdateInterval=60*60*1000;
let leaderboardRefreshInFlight=null,leaderboardLastSubmit=0,leaderboardLastRefresh=0,progressOwnerId=null;
function progressKey(){return user?.id?`nv_progress_v2_${user.id}`:null}
function lastPlayedKey(){return user?.id?`nv_last_played_${user.id}`:'nv_last_played'}
function formatPlaytime(seconds){const total=Math.max(0,Math.floor(Number(seconds)||0)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:total?`${minutes}m`:'0 minutes'}
function renderProfileStats(){const name=$('#profile-page-name'),handle=$('#profile-page-handle'),largeAvatar=$('#profile-page-avatar'),last=$('#profile-last-played'),topLast=$('#profile-page-last-online'),time=$('#profile-playtime'),trophies=$('#profile-game-trophy-count'),bar=$('#profile-game-progress');if(name)name.textContent=user?.displayName||user?.username||'Discord not linked';if(handle)handle.textContent=linked?`Discord · @${user?.username||'connected'} · ${member===true?'Nexa Verse member':member===false?'Not in Nexa Verse':'Checking server status'}`:'Account status · Not connected';if(largeAvatar){largeAvatar.replaceChildren();const source=$('#profile-avatar img');if(source?.src){const image=document.createElement('img');image.src=source.src;image.alt='Discord avatar';largeAvatar.append(image)}else largeAvatar.textContent='◉'}const stamp=Number(localStorage.getItem(lastPlayedKey())||0),when=stamp?new Date(stamp):null,relative=when?new Intl.RelativeTimeFormat(undefined,{numeric:'auto'}).format(Math.round((stamp-Date.now())/60000),'minute'):'Never played';if(last)last.textContent=`Last time played · ${relative}`;if(topLast)topLast.textContent=stamp?`LAST TIME PLAYED · ${relative.toUpperCase()}`:'LAST TIME PLAYED · NEVER';if(time)time.textContent=`Total playtime · ${formatPlaytime(playerProgress.playtimeSeconds)}`;const count=Math.max(0,Math.min(55,Math.floor(playerProgress.trophiesEarned||0)));if(trophies)trophies.textContent=`${count} / 55`;if(bar)bar.style.width=`${count/55*100}%`}
function persistProgress(){const key=progressKey();if(key)localStorage.setItem(key,JSON.stringify(playerProgress))}
function applyAccountProgress(){if(!linked||!user?.id)return;if(progressOwnerId!==user.id){progressOwnerId=user.id;leaderboardLastSubmit=0;leaderboardLastRefresh=0;const key=progressKey();let stored;try{stored=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(stored&&Number.isFinite(stored.playtimeSeconds)){playerProgress={completionPercent:Math.max(0,Math.min(100,Math.floor(stored.completionPercent||0))),trophiesEarned:Math.max(0,Math.min(55,Math.floor(stored.trophiesEarned||0))),playtimeSeconds:Math.max(0,Math.floor(stored.playtimeSeconds||0))}}else{const seed=seededProgress[String(user.username||'').toLowerCase()];playerProgress=seed?{...seed}: {completionPercent:0,trophiesEarned:0,playtimeSeconds:0};persistProgress()}}renderTrophyProgress();renderProfileStats();if(member===true)syncLeaderboard(false)}
async function syncLeaderboard(force=false){if(!linked||member!==true||!user?.id||leaderboardRefreshInFlight)return leaderboardRefreshInFlight;const now=Date.now(),shouldSubmit=now-leaderboardLastSubmit>=leaderboardUpdateInterval,shouldRefresh=force||now-leaderboardLastRefresh>=leaderboardUpdateInterval;if(!shouldSubmit&&!shouldRefresh)return;leaderboardRefreshInFlight=(async()=>{try{if(shouldSubmit){leaderboardLastSubmit=Date.now();const submitted=await fetch('/api/leaderboard',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(playerProgress),cache:'no-store'});if(!submitted.ok)leaderboardLastSubmit=Date.now()-leaderboardUpdateInterval+60_000}if(shouldRefresh){const response=await fetch('/api/leaderboard',{method:'GET',cache:'no-store'}),data=await response.json();if(response.ok){renderLeaderboard(data.entries||[]);leaderboardLastRefresh=Date.now()}}}catch{}finally{leaderboardRefreshInFlight=null}})();return leaderboardRefreshInFlight}
function renderLeaderboard(entries){const list=$('#leaderboardRows');if(!list)return;list.replaceChildren();if(!entries.length){const empty=document.createElement('li');empty.className='leaderboard-empty';empty.textContent='No launcher scores have been recorded yet.';list.append(empty);return}for(const [index,entry] of entries.slice(0,10).entries()){const row=document.createElement('li');row.className='leaderboard-row';const rank=document.createElement('span');rank.className='leaderboard-rank';rank.textContent=String(entry.rank||index+1).padStart(2,'0');const info=document.createElement('span');info.className='leaderboard-player';const name=document.createElement('b');name.textContent=entry.displayName||entry.username||'Nexa Verse player';const details=document.createElement('small');details.textContent=`${Math.floor((entry.playtimeSeconds||0)/3600)}h playtime · ${entry.trophiesEarned||0}/55 trophies`;info.append(name,details);const score=document.createElement('b');score.className='leaderboard-score';score.textContent=String(entry.score||0);row.append(rank,info,score);list.append(row)}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function update(){play.disabled=!linked||member!==true||!validGameApp(folder);$('#accountSetting').textContent=linked?`Connected as ${user?.displayName||user?.username||'Discord user'}${member===false?' • Join Nexa Verse to unlock':member===null?' • Membership check unavailable':''}`:'Not connected';$('#accountBtn').textContent=linked?'Disconnect':'Connect Discord';const display=validGameApp(folder)?gameAppName(folder):'Not linked';$('#game-folder').textContent=display.length>25?'…'+display.slice(-23):display;$('#game-folder-display').textContent=validGameApp(folder)?display:'No GTA VI application linked';$('#gameFolderSetting').textContent=validGameApp(folder)?display+' · '+folder:'Link your GTA VI application (.exe).';$('#profile-name').textContent=user?.displayName||user?.username||'Discord not linked';$('#profile-handle').textContent=linked?`Discord · @${user?.username||'connected'} · ${member===true?'Nexa Verse member':member===false?'Not in Nexa Verse':'Checking server status'}`:'Account status · Not connected';$('#profile-status').textContent=linked?member===true?'Connected':member===false?'Join server':'Retrying':'Offline';const avatar=$('#profile-avatar');avatar.replaceChildren();if(user?.avatar&&/^https:\/\/cdn\.discordapp\.com\//.test(user.avatar)){const img=document.createElement('img');img.src=user.avatar;img.alt='Discord avatar';avatar.append(img)}else avatar.textContent='◉';renderProfileStats();const gate=$('#gate'),connect=$('#connect'),check=$('#checkMembership');if(linked&&member===true){gate.classList.add('hidden')}else{gate.classList.remove('hidden');if(linked){$('#gate-title').textContent=member===false?'Join the Nexa Verse server':'Discord is still linked';$('#gate-message').textContent=member===false?'Your Discord account is saved. Join the Nexa Verse Discord server, then check membership to unlock the launcher.':'Your Discord account is saved. Discord could not verify server membership right now. Retry the check; you do not need to link again.';connect.classList.add('hidden');check.classList.remove('hidden')}else{$('#gate-title').textContent='Link your Discord';$('#gate-message').textContent='Link your Discord account and join the Nexa Verse server. Both are required to access the launcher.';connect.classList.remove('hidden');check.classList.add('hidden')}}}
function showDiscordConsent(){const gate=$('#gate');$('#gate-title').textContent='Update Discord permissions';$('#gate-message').textContent='Discord did not grant permission to check whether you are in Nexa Verse. Refresh Discord permissions once to continue.';const connect=$('#connect');connect.textContent='Refresh Discord permissions';connect.classList.remove('hidden');$('#checkMembership').classList.remove('hidden');gate.classList.remove('hidden')}
async function refresh(force=false){if(statusRefresh){await statusRefresh;if(!force)return;return refresh(true)}statusRefresh=(async()=>{const previouslyVerified=linked&&member===true;try{const response=await fetch(`/api/status${force?'?force=1':''}`,{cache:'no-store'}),s=await response.json();linked=s.linked===true;consentRequired=s.needsConsent===true;if(!linked){member=null;user=null;consentRequired=false;localStorage.removeItem('nv_verified_discord_user')}else{user=s.user||user;if(s.member===true){member=true;consentRequired=false;if(user?.id)localStorage.setItem('nv_verified_discord_user',user.id)}else if(s.member===false){member=false;consentRequired=false;localStorage.removeItem('nv_verified_discord_user')}else if(!consentRequired&&(previouslyVerified||(user?.id&&localStorage.getItem('nv_verified_discord_user')===user.id)))member=true;else member=null}if(!s.configured)$('#auth-note').textContent='OAuth setup required • See README.md to configure Discord';update();applyAccountProgress();if(linked&&member===true)refreshModpackStatus();else{modpackUnlocked=false;modpackOwnerId=null;modpackStatusCheckedAt=0;renderModpack()}if(consentRequired)showDiscordConsent()}catch{if(linked)update()}})();try{await statusRefresh}finally{statusRefresh=null}}
$('#connect').onclick=async()=>{try{const r=await fetch('/api/auth/start',{method:'POST'}),j=await r.json();if(!r.ok||!j.url)return toast(j.error||'Could not start Discord linking.');if(window.launcher)await window.launcher.openExternal(j.url);else location.href=j.url}catch{toast('Could not start Discord linking.')}};$('#checkMembership').onclick=async()=>{const b=$('#checkMembership');b.disabled=true;b.textContent='Checking…';await refresh(true);b.disabled=false;b.textContent='Check membership';if(member===true)toast('Nexa Verse membership verified');else if(member===false)toast('Join the Nexa Verse Discord server first');else toast('Membership check unavailable; your Discord stays linked')};$('#dismiss').onclick=()=>toast(linked?'Your Discord link is saved.':'Link Discord and join the server to unlock Play.');
$('#accountBtn').onclick=async()=>{if(!linked){$('#connect').click();return}await fetch('/auth/logout',{method:'POST'});linked=false;member=null;user=null;modpackUnlocked=false;modpackOwnerId=null;modpackStatusCheckedAt=0;renderModpack();localStorage.removeItem('nv_verified_discord_user');update();toast('Discord disconnected')};
const discordActivityButton=$('#discordActivityBtn');
let discordActivityEnabled=localStorage.getItem('nv_discord_activity')!=='false';
function renderDiscordActivity(){if(!discordActivityButton)return;discordActivityButton.textContent=discordActivityEnabled?'Turn off':'Turn on';$('#discordActivityInfo').textContent=discordActivityEnabled?'Enabled · Shows Nexa Verse Launcher in Discord while the Discord desktop app is open.':'Disabled · Your Discord profile will not show launcher activity.'}
window.launcher?.setDiscordActivity(discordActivityEnabled);
renderDiscordActivity();
discordActivityButton?.addEventListener('click',async()=>{discordActivityEnabled=!discordActivityEnabled;localStorage.setItem('nv_discord_activity',String(discordActivityEnabled));const result=await window.launcher?.setDiscordActivity(discordActivityEnabled);renderDiscordActivity();toast(discordActivityEnabled?(result?.ok?'Discord activity enabled':'Discord activity enabled; open Discord desktop to display it'):'Discord activity disabled')});
play.onclick=async()=>{if(!validGameApp(folder)){toast('Link GTA6.exe, GTA VI.exe, or GTAVI.exe in Settings before playing.');return}if(!linked||member!==true)return;play.disabled=true;try{const response=await fetch('/api/play',{cache:'no-store'}),j=await response.json();if(j.needsConsent){consentRequired=true;member=null;update();showDiscordConsent()}else if(response.status===503){await refresh(true);toast(j.error||'Could not verify Nexa Verse membership.')}else if(!response.ok){toast(j.error||'Join the Nexa Verse server before playing.')}else{const launched=await window.launcher?.launchGame(folder);if(launched?.ok){localStorage.setItem(lastPlayedKey(),String(Date.now()));renderProfileStats();toast('GTA VI launched.')}else toast(launched?.error||'Use the installed desktop launcher to start the linked GTA VI application.')}}catch{toast('Could not verify membership or start GTA VI. Try again shortly.')}finally{update()}};
async function chooseGameFolder(){if(!window.launcher){toast('Use the desktop launcher to link your GTA VI application.');return}try{const picked=await window.launcher.pickGameApplication();if(picked){folder=picked;localStorage.setItem('nv_game_folder',folder);update();toast('GTA VI application linked')}}catch(error){toast(error.message||'Choose a GTA VI application (.exe).')}}
$('#folderBtn').onclick=chooseGameFolder;$('#playFolderBtn').onclick=chooseGameFolder;const nameInput=$('#playerName');nameInput.value=localStorage.getItem('nv_player_name')||'';
$('#saveName').onclick=()=>{const v=nameInput.value.trim();if(!v)return toast('Enter a player name first.');localStorage.setItem('nv_player_name',v);toast(`Player name saved: ${v}`)};
function setUpdateBadge(s){const badge=$('#updateBadge');if(!badge)return;const icon=badge.querySelector('.update-badge-icon'),label=badge.querySelector('.update-badge-text');badge.classList.remove('checking','available','current','error','downloading','ready','dev');badge.classList.add(s.status);badge.title=s.detail||'Launcher update status';if(s.status==='current'){icon.textContent='✓';label.textContent='ALL UP TO DATE'}else if(s.status==='available'||s.status==='downloading'||s.status==='ready'){icon.textContent='!';label.textContent=s.status==='ready'?'UPDATE READY':'UPDATE AVAILABLE'}else if(s.status==='error'){icon.textContent='!';label.textContent='UPDATE CHECK FAILED'}else if(s.status==='dev'){icon.textContent='·';label.textContent='DEV BUILD'}else{icon.textContent='…';label.textContent='CHECKING UPDATES'}$('#updateInfo').textContent=s.detail||s.status;if(s.status==='ready'){const b=$('#updateBtn');b.textContent='Restart to update';b.onclick=()=>window.launcher.installUpdate()}}
$('#updateBtn').onclick=async()=>{if(!window.launcher){toast('Automatic updates are available in the installed launcher.');return}setUpdateBadge({status:'checking',detail:'Checking for launcher updates…'});const r=await window.launcher.checkUpdates();if(r.status==='error'||r.status==='dev')setUpdateBadge(r)};
$('#updateBadge').onclick=async()=>{if(!window.launcher)return;if($('#updateBadge').classList.contains('ready')){window.launcher.installUpdate();return}setUpdateBadge({status:'checking',detail:'Checking for launcher updates…'});const r=await window.launcher.checkUpdates();if(r.status==='error'||r.status==='dev')setUpdateBadge(r)};
window.launcher?.onUpdateStatus(s=>{setUpdateBadge(s);if(s.status==='current')toast('Launcher is up to date.')});
let modpackUnlocked=false,modpackOwnerId=null,modpackStatusRefresh=null,modpackStatusCheckedAt=0;
const modpackItems=['God Mode','Unlimited Health','Unlimited Stamina','Unlimited Breath','Never Detected by Police','Max Police Stars','Super Game Speed','Unlimited Money','Max Stats','No Reload','Unlimited Ammo','God Mode Vehicle','Unlimited Vehicle Health'];
const modpackSwitches=new Map(modpackItems.map(name=>[name,false]));
async function refreshModpackStatus(force=false){if(!linked||member!==true||!user?.id){modpackUnlocked=false;modpackOwnerId=null;renderModpack();return}if(modpackOwnerId!==user.id){modpackOwnerId=user.id;modpackUnlocked=false;modpackStatusCheckedAt=0;renderModpack()}if(modpackStatusRefresh)return modpackStatusRefresh;if(!force&&(modpackUnlocked||Date.now()-modpackStatusCheckedAt<60000))return;modpackStatusRefresh=(async()=>{try{const response=await fetch('/api/modpack/status',{method:'POST',cache:'no-store'}),result=await response.json();if(response.ok){modpackUnlocked=result.unlocked===true;modpackStatusCheckedAt=Date.now();renderModpack()}}catch{}finally{modpackStatusRefresh=null}})();return modpackStatusRefresh}
function renderModpack(){const title=$('#modpackStateTitle'),message=$('#modpackStateMessage'),icon=$('#modpackPageLock'),lockButton=$('#modpackLockButton'),options=$('#modpackOptions');if(title)title.textContent=modpackUnlocked?'Modpack unlocked':'Modpack is locked';if(message)message.textContent=modpackUnlocked?'Access granted on this device.':'Click the lock icon beside Modpack in the navigation to enter the 8 digit access code.';if(icon)icon.textContent=modpackUnlocked?'🔓':'🔒';if(lockButton){lockButton.textContent=modpackUnlocked?'🔓':'🔒';lockButton.title=modpackUnlocked?'Modpack unlocked on this device':'Unlock Modpack with access code';lockButton.setAttribute('aria-label',lockButton.title)}if(options)options.classList.toggle('hidden',!modpackUnlocked);const list=$('#modpackToggleList');if(list&&!list.childElementCount){for(const name of modpackItems){const row=document.createElement('div');row.className='modpack-option';const label=document.createElement('span');label.textContent=name;const toggle=document.createElement('button');toggle.type='button';toggle.className='modpack-toggle';toggle.setAttribute('role','switch');toggle.setAttribute('aria-checked','false');toggle.innerHTML='<span>OFF</span><span>ON</span>';toggle.addEventListener('click',()=>{const next=!modpackSwitches.get(name);modpackSwitches.set(name,next);toggle.classList.toggle('is-on',next);toggle.setAttribute('aria-checked',String(next))});row.append(label,toggle);list.append(row)}}}function showPage(page){document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===page));document.querySelectorAll('.dock-tile[data-page]').forEach(n=>{const selected=n.dataset.page===page;n.classList.toggle('selected',selected);n.setAttribute('aria-current',selected?'page':'false')});document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active-page',p.id===page))}
const modpackDialog=$('#modpackCodeDialog'),modpackInput=$('#modpackCodeInput');
$('#leaderboardRefresh')?.addEventListener('click',()=>syncLeaderboard(true));
setInterval(async()=>{try{if(await window.launcher?.isGameRunning()){playerProgress.playtimeSeconds+=60;persistProgress();renderProfileStats();await syncLeaderboard(false)}}catch{}},60_000);
document.querySelectorAll('.nav[data-page]').forEach(b=>b.onclick=()=>{showPage(b.dataset.page);if(b.dataset.page==='friends')syncLeaderboard(true)});
$('#modpackLockButton')?.addEventListener('click',()=>{if(modpackUnlocked){toast('Modpack is already unlocked on this device.');return}modpackDialog.classList.remove('hidden');modpackInput.value='';modpackInput.focus()});
