$('#modpackCodeForm')?.addEventListener('submit',async event=>{event.preventDefault();const code=modpackInput.value.trim();if(!/^\d{8}$/.test(code)){toast('Enter all 8 digits.');return}const submit=modpackDialog.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent='Checking…';try{const response=await fetch('/api/modpack/redeem',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code}),cache:'no-store'}),result=await response.json();if(!response.ok){toast(result.error||'Could not redeem this code.');modpackInput.select();return}modpackUnlocked=result.unlocked===true;modpackOwnerId=user?.id||null;modpackStatusCheckedAt=Date.now();renderModpack();modpackDialog.classList.add('hidden');showPage('modpack');toast('Modpack unlocked for this Discord account.')}catch{toast('Modpack redemption service is unavailable. Try again shortly.')}finally{submit.disabled=false;submit.textContent='Unlock Modpack'}});
renderModpack();
async function refreshLauncherPresence(){const badge=$('#connectedCount');if(!badge)return;if(!linked||member!==true){badge.textContent='0';badge.title='Link Discord and verify Nexa Verse membership to be counted';return}try{const r=await fetch('/api/presence',{method:'POST',cache:'no-store'}),data=await r.json();badge.textContent=String(Number.isFinite(data.connected)?data.connected:0);badge.title=data.scope==='network'?'Players with active Nexa Verse launcher sessions across all devices':'Active sessions on this launcher copy; shared counting service is not configured'}catch{badge.textContent='—';badge.title='Launcher presence service is unavailable'}}
refresh();setInterval(refresh,15000);refreshLauncherPresence();setInterval(refreshLauncherPresence,20000);
const launchCountdown=$('#launchCountdown'),launchDate=new Date(2026,10,19,0,0,0,0);
function updateLaunchCountdown(){if(!launchCountdown)return;const remaining=Math.max(0,Math.ceil((launchDate.getTime()-Date.now())/1000)),days=Math.floor(remaining/86400),hours=Math.floor(remaining%86400/3600),minutes=Math.floor(remaining%3600/60),seconds=remaining%60;launchCountdown.textContent=`${String(days).padStart(2,'0')}d ${String(hours).padStart(2,'0')}h ${String(minutes).padStart(2,'0')}m ${String(seconds).padStart(2,'0')}s`;launchCountdown.title=remaining?`${days} days, ${hours} hours, ${minutes} minutes, ${seconds} seconds until November 19, 2026`:'November 19, 2026 has arrived'}
