function refreshController(){const pads=Array.from(navigator.getGamepads?.()||[]).filter(p=>p&&p.connected);const panel=$('#controller-name'),status=$('#controller-status'),icon=$('#controller-icon-image');if(!pads.length){panel.textContent='No controller detected';status.textContent='Use mouse and keyboard or launch DS4Windows for PlayStation pads';icon.src='/controller-mouse.webp';icon.alt='Mouse and keyboard';return}const pad=pads[0],id=pad.id||'Gamepad',isScuf=/(scuf|\bdgm20\b|usb[\s_-]*microphone)/i.test(id),isPs5=/(dualsense|playstation 5|ps5|vendor:\s*054c\s+product:\s*(0ce6|0df2))/i.test(id),isPs4=/(dualshock|playstation|sony|wireless controller|vendor:\s*054c)/i.test(id),isXbox=/(xbox|microsoft|vendor:\s*045e)/i.test(id);panel.textContent=isScuf?'SCUF Controller':id.split('(Vendor:')[0].trim().slice(0,42)||'Game controller';status.textContent=`Connected · Player ${pad.index+1}${pads.length>1?` · ${pads.length} controllers`:''}`;if(isScuf){icon.src='/controller-scuf.png';icon.alt='SCUF controller'}else if(isPs5){icon.src='/controller-ps5.png';icon.alt='PlayStation 5 DualSense controller'}else if(isPs4){icon.src='/controller-ps4.png';icon.alt='PlayStation 4 DualShock controller'}else if(isXbox){icon.src='/controller-xbox.png';icon.alt='Xbox controller'}else{icon.src='/controller-generic.svg';icon.alt='Game controller'}}
window.addEventListener('gamepadconnected',refreshController);window.addEventListener('gamepaddisconnected',refreshController);setInterval(refreshController,1200);refreshController();

let controllerTestFrame=0,controllerTestActive=false;
const controllerTestDialog=$('#controllerTestDialog'),controllerButtonGrid=$('#controllerButtonGrid');
function renderControllerTestFrame(){if(!controllerTestActive)return;const pads=Array.from(navigator.getGamepads?.()||[]).filter(pad=>pad?.connected),pad=pads[0],status=$('#controllerTestStatus');if(!pad){status.textContent='No controller detected · Connect or wake a controller to begin.';for(const side of ['left','right']){const dot=$(`#${side}StickDot`),value=$(`#${side}StickValue`);dot.style.left='50%';dot.style.top='50%';value.textContent='X 0.00 · Y 0.00'}controllerButtonGrid.replaceChildren();controllerTestFrame=requestAnimationFrame(renderControllerTestFrame);return}status.textContent=`${pad.id||'Game controller'} · Connected${pads.length>1?` · ${pads.length} controllers` : ''}`;for(const [side,xIndex] of [['left',0],['right',2]]){const x=Math.max(-1,Math.min(1,Number(pad.axes?.[xIndex])||0)),y=Math.max(-1,Math.min(1,Number(pad.axes?.[xIndex+1])||0));const dot=$(`#${side}StickDot`);dot.style.left=`${50+x*42}%`;dot.style.top=`${50+y*42}%`;$(`#${side}StickValue`).textContent=`X ${x.toFixed(2)} · Y ${y.toFixed(2)}`}const labels=['A / Cross','B / Circle','X / Square','Y / Triangle','L1 / LB','R1 / RB','L2 / LT','R2 / RT','Select / View','Start / Menu','L3','R3','D-pad Up','D-pad Down','D-pad Left','D-pad Right','Home'];controllerButtonGrid.replaceChildren();(pad.buttons||[]).slice(0,labels.length).forEach((button,index)=>{const cell=document.createElement('span');cell.className='controller-button-test'+(button?.pressed?' pressed':'');cell.textContent=labels[index]||`Button ${index+1}`;cell.setAttribute('aria-label',`${cell.textContent} ${button?.pressed?'pressed':'not pressed'}`);controllerButtonGrid.append(cell)});controllerTestFrame=requestAnimationFrame(renderControllerTestFrame)}
function closeControllerTest(){controllerTestActive=false;if(controllerTestFrame)cancelAnimationFrame(controllerTestFrame);controllerTestFrame=0;controllerTestDialog.hidden=true;$('#controllerTestBtn')?.focus()}
$('#controllerTestBtn')?.addEventListener('click',()=>{controllerTestActive=true;controllerTestDialog.hidden=false;renderControllerTestFrame();$('#controllerTestClose').focus()});
$('#controllerTestClose')?.addEventListener('click',closeControllerTest);
controllerTestDialog?.querySelector('[data-close-controller-test]')?.addEventListener('click',closeControllerTest);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&controllerTestActive)closeControllerTest()});$('#ds4WindowsBtn')?.addEventListener('click',async()=>{if(!window.launcher?.launchDS4Windows)return toast('DS4Windows launching is available in the Windows app.');const result=await window.launcher.launchDS4Windows();if(result?.canceled)return;toast(result?.ok?'DS4Windows opened. Connect your controller, then check the controller card.':result?.error||'Could not open DS4Windows.')});

function applySocialState(next){
  if(next?.type==='friends')next={status:'ready',friends:next.friends||[]};
  else if(next?.type==='status')next={status:next.status,friends:socialState.friends};
  else if(next?.type==='error')next={status:'error',message:next.message,friends:socialState.friends};
  socialState={...socialState,...(next||{})};
  const panel=$('#socialPanel'),cards=$('#socialCards'),button=$('#socialConnect');
  if(!panel||!cards||!button)return;
  const ready=socialState.status==='ready',friends=Array.isArray(socialState.friends)?socialState.friends:[];
