/* PS5-inspired home layout, retaining the Nexa Verse GTA VI palette. */
:root{--bg:#071323;--blue:#398cff;--cyan:#55d8ff;--pink:#ff49b5;--yellow:#ffc84b}
.app{background:radial-gradient(ellipse at 70% 16%,#174979 0,#101b37 42%,#080b1b 100%)}
.topbar{background:linear-gradient(90deg,#091324f5,#121631f0);border-bottom-color:#4d92d44d;backdrop-filter:blur(16px)}
.nav.active:after{background:linear-gradient(90deg,var(--blue),var(--pink),var(--yellow))}
.home-dock{width:min(91%,1420px);margin:20px auto 0;display:flex;align-items:flex-start;gap:10px;overflow-x:auto;padding:4px 3px 12px;scrollbar-width:thin;scrollbar-color:#6388cc55 transparent}
.dock-tile{width:82px;height:82px;flex:0 0 82px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:9px;border:1px solid #ffffff14;border-radius:16px;background:linear-gradient(145deg,#131c32ed,#0a1426f0);color:#dceaff;text-decoration:none;cursor:pointer;box-shadow:0 8px 26px #0005;transition:transform .18s ease,border-color .18s ease,background .18s ease,box-shadow .18s ease}
.dock-tile:hover,.dock-tile:focus-visible{transform:translateY(-4px) scale(1.04);border-color:#7ac9ff99;background:linear-gradient(145deg,#1d3354,#111a34);box-shadow:0 12px 30px #2179e744,0 0 18px #ed59bc22;outline:none}
.dock-tile>img{width:36px;height:36px;object-fit:contain;border-radius:9px;filter:drop-shadow(0 0 8px #398cff45)}
.dock-tile>span:last-child{font-size:10px;font-weight:700;white-space:nowrap}
.dock-glyph{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:linear-gradient(135deg,#398cff,#8054ed 52%,#e348b7);color:#fff;font-size:19px;font-weight:900;box-shadow:0 5px 18px #398cff55}
.discord-dock{background:linear-gradient(145deg,#171d3c,#10152b);border-color:#5868e877}.discord-dock img{width:40px;height:40px;border-radius:12px}
.hero{margin-top:10px;width:min(91%,1420px);height:min(47vh,390px);min-height:310px;border-color:#66a9ec70;border-radius:18px;box-shadow:0 20px 70px #0009,0 0 32px #398cff15}
.hero-shade{background:linear-gradient(90deg,#071527e8 0%,#132b50c9 43%,#281d4d70 72%,#0b1023e3 100%),linear-gradient(0deg,#0b1225ba,transparent 48%)}
.install-strip,.status-card,.welcome,.home-panel{background:linear-gradient(145deg,#14213aee,#0d1629f5);border-color:#5792d455;box-shadow:0 10px 28px #0005}
.play-button{border-color:#ffc84b;background:linear-gradient(105deg,#338df4 0%,#7851ff 46%,#f14ba9 82%,#f8b746 100%);box-shadow:0 10px 32px #517eff66,inset 0 1px #ffffff66}
.updates-panel{position:relative;inset:auto;width:min(91%,1420px);height:auto;max-height:none;margin:18px auto 22px;padding:12px 14px;display:block;border:1px solid #5792d455;border-radius:16px;background:linear-gradient(115deg,#101b31f5,#11142bf5);box-shadow:0 12px 34px #0006}
.updates-heading{margin-bottom:10px}.updates-embed{display:flex;gap:10px;overflow-x:auto;overflow-y:hidden;padding:0 0 5px;border:0;background:transparent;scroll-snap-type:x mandatory;scrollbar-width:thin;scrollbar-color:#8b68ce55 transparent}
.update-preview-link{flex:0 0 clamp(220px,27vw,360px);height:clamp(112px,14vw,180px);overflow:hidden;border:1px solid #ffffff1c;border-radius:11px;background:#0b1323;scroll-snap-align:start}
.updates-embed img{width:100%;height:100%;object-fit:cover;object-position:top center;border-radius:10px}
.updates-embed .update-preview-link+.update-preview-link{margin:0;padding:0;border:1px solid #ffffff1c}
#play{overflow-y:auto;scrollbar-color:#6388cc55 #071323}
